  function phonePreviewWrap_(scaleHtml){
    var spec=phonePreviewSpec_(state.devicePreview);
    if(!spec)return scaleHtml;
    var caption=cgT(spec.labelKey);
    return '<div class="cg-phone-preview" data-phone-id="'+attr(spec.id)+'" style="--cg-phone-w:'+spec.w+'px;--cg-phone-h:'+spec.h+'px"><div class="cg-phone-preview__bezel"><div class="cg-phone-preview__frame" role="img" aria-label="'+attr(caption)+'"><span class="cg-phone-preview__island" aria-hidden="true"></span><div class="cg-phone-preview__screen">'+scaleHtml+'</div><span class="cg-phone-preview__home" aria-hidden="true"></span></div></div><p class="cg-phone-preview__caption">'+esc(caption)+'</p></div>';
  }
  function fitPhonePreviewFrame_(){
    var root=document.getElementById(APP_ID);
    if(!root)return;
    var host=root.querySelector('.cg-phone-preview');
    var frame=root.querySelector('.cg-phone-preview__frame');
    var bezel=root.querySelector('.cg-phone-preview__bezel');
    if(!host||!frame||!bezel)return;
    frame.style.transform='none';
    var stage=root.querySelector('.cg-preview-stage');
    var availW=Math.max(160, host.clientWidth);
    var availH=stage?Math.max(220, stage.clientHeight-88):host.clientHeight;
    var fw=frame.offsetWidth||1;
    var fh=frame.offsetHeight||1;
    var s=Math.min(1, availW/fw, availH/fh);
    if(!isFinite(s)||s<=0)s=1;
    frame.style.transform='scale('+s+')';
    bezel.style.height=Math.round(fh*s)+'px';
  }
