  function passportMaterialSelectHtml(){var p=state.passport;var rows=CARD_MATERIALS.map(function(m){return'<option value="'+attr(m.id)+'"'+(p.material===m.id?' selected':'')+'>'+esc(m.zhName)+' · '+esc(m.enName)+'</option>';}).join('');return'<label class="wide"><span>卡片材質</span><select size="6" class="cg-scroll-select" data-passport-material-select>'+rows+'</select></label>';}
  function filteredBackplatePresets_(){var g=state.passport.backplateCat||'all';return PASSPORT_BACKPLATE_PRESETS.filter(function(p){if(g==='all')return true;if(g==='taxon')return!!p.taxGroup;return String(p.group||p.cat||'all')===g;});}
  function applyBackplatePreset_(id){state.passport.backplatePresetId=String(id||'');var pr=PASSPORT_BACKPLATE_PRESETS.filter(function(x){return String(x.id)===String(id);})[0];if(pr){state.back.cat=pr.cat||'all';state.back.search=pr.kw||'';state.passport.autoBack=true;state.passport.manualBackId='';state.passport.backplateOverride=false;}}
  function passportMaterialGalleryHtml(){var p=state.passport,list=filteredCardMaterials(),maxShow=36,chips=MATERIAL_GALLERY_CATS.map(function(pair){return'<button type="button" class="cg-mat-cat-chip '+(p.materialCat===pair[0]?'is-active':'')+'" data-passport-material-cat="'+attr(pair[0])+'">'+esc(pair[1])+'</button>';}).join(''),tiles=list.slice(0,maxShow).map(function(m){return'<button type="button" class="cg-mat-tile'+(p.material===m.id?' is-active':'')+'" data-passport-material="'+attr(m.id)+'"><span class="cg-mat-tile__swatch" style="background:'+esc(m.swatch)+'"></span><span class="cg-mat-tile__badge">'+esc(m.badgeZh)+'</span><strong class="cg-mat-tile__zh">'+esc(m.zhName)+'</strong><span class="cg-mat-tile__en">'+esc(m.enName)+'</span><span class="cg-mat-tile__desc">'+esc(m.description)+'</span></button>';}).join(''),more=list.length>maxShow?'<p class="cg-panel__hint">顯示 '+maxShow+' / '+list.length+' 種材質；請用搜尋或分類縮小範圍。</p>':'<p class="cg-panel__hint">共 '+list.length+' 種卡片材質可選。</p>';return'<div class="cg-material-gallery" data-cg-tour-target="material-gallery"><h4 class="cg-material-gallery__title">卡片材質</h4><p class="cg-material-gallery__sub">點選材質即時更新右側卡片護照預覽。</p><input class="cg-search cg-mat-search" type="search" data-passport-material-search placeholder="搜尋材質（中英）" value="'+attr(p.materialSearch||'')+'"><div class="cg-mat-cat-row">'+chips+'</div><div class="cg-mat-tile-grid">'+tiles+'</div>'+more+'</div>';}
  function passportBackplateGalleryHtml(){var p=state.passport,list=filteredBackplatePresets_(),cur=String(p.backplatePresetId||''),chips=BACKPLATE_GALLERY_CATS.map(function(pair){return'<button type="button" class="cg-bp-cat-chip '+(p.backplateCat===pair[0]?'is-active':'')+'" data-backplate-cat="'+attr(pair[0])+'">'+esc(pair[1])+'</button>';}).join(''),tiles=list.map(function(o){return'<button type="button" class="cg-bp-tile'+(cur===String(o.id)?' is-active':'')+'" data-backplate-preset="'+attr(o.id)+'"><strong class="cg-bp-tile__zh">'+esc(o.zh)+'</strong>'+(o.hint?'<span class="cg-bp-tile__hint">'+esc(o.hint)+'</span>':'')+'</button>';}).join('');return'<div class="cg-backplate-gallery" data-cg-tour-target="backplate-gallery"><h4 class="cg-backplate-gallery__title">背板主題</h4><p class="cg-backplate-gallery__sub">選擇背板風格後會自動匹配素材庫；也可在下方手動更換具體背板圖。</p><div class="cg-bp-cat-row">'+chips+'</div><div class="cg-bp-tile-grid">'+tiles+'</div></div>';}
  function passportBackplatePresetSelectHtml(){var cur=String(state.passport.backplatePresetId||'');var opts=PASSPORT_BACKPLATE_PRESETS.map(function(o){return'<option value="'+attr(o.id)+'"'+(cur===String(o.id)?' selected':'')+'>'+esc(o.zh)+'</option>';}).join('');return'<label class="wide"><span>背板主題</span><select size="6" class="cg-scroll-select" data-passport-backplate-preset>'+opts+'</select></label>';}
  function materialControls(){var p=state.passport,rv=reviewMeta(),rk=normalizeRarityTier(p.rarityTier),tierOrder=['C','U','R','SR','SSR','UR','HR','SEC','AR','SAR','N','MG'],opts=tierOrder.map(function(id){var on=rk===id?' selected':'';var m=rarityMetaByTier(id);return'<option value="'+attr(id)+'"'+on+'>'+esc(id+' · '+m.zh)+'</option>';}).join(''),pillSel=rv.key==='not-reviewed'?'<label><span>未審角標</span><select data-passport="reviewBadgeVariant"><option value="classic"'+(p.reviewBadgeVariant!=='mesa'?' selected':'')+'>經典</option><option value="mesa"'+(p.reviewBadgeVariant==='mesa'?' selected':'')+'>橫條</option></select></label>':'';return passportMaterialGalleryHtml()+passportBackplateGalleryHtml()+'<details class="cg-step-notes cg-step-notes--inline"><summary>材質／背板快速選單</summary><div class="cg-field-deck cg-field-deck--compact cg-material-picks" data-cg-tour-target="card-material">'+passportMaterialSelectHtml()+passportBackplatePresetSelectHtml()+'</div></details><div class="cg-field-deck cg-field-deck--compact cg-field-deck--passport-meta"><label><span>審核狀態</span><input readonly value="'+attr(rv.zh)+'"></label><label><span>稀有度（預覽）</span><select data-passport="rarityTier">'+opts+'</select></label>'+pillSel+'<label class="cg-check"><input type="checkbox" data-passport-check="autoBack" '+(p.autoBack?'checked':'')+'> 自動匹配背板</label></div>'+backPickerCompact();}
  function filteredBacks(){var q=norm(state.back.search),c=state.back.cat,rec=matchBack().asset;var list=getAssets().filter(function(a){return(!q||a.searchBlob.indexOf(q)>=0)&&(c==='all'||a.category===c||a.fallbackGroup===c);});if(rec)list.sort(function(a,b){return(a.id===rec.id?-1:0)+(b.id===rec.id?1:0);});return list;}
