  function fitPassportTextEl_(el,opts){
    opts=opts||{};
    if(!el||!el.isConnected)return;
    var inner=el.querySelector('i')||el;
    inner.style.fontSize='';
    inner.style.lineHeight=opts.lineHeight||'1.08';
    inner.style.whiteSpace='nowrap';
    inner.style.overflow='hidden';
    inner.style.textOverflow='clip';
    inner.style.display='block';
    inner.style.maxWidth='100%';
    var box=el.closest('.ppc-sci-row')||el.parentElement;
    if(!box||box.clientWidth<1)return;
    var limit=box.clientWidth;
    var cs=window.getComputedStyle(inner);
    var maxSize=Number(opts.maxFont)||parseFloat(cs.fontSize)||34;
    var floor=Math.max(Number(opts.minFont)||10,Math.round(maxSize*0.32));
    var size=maxSize;
    inner.style.fontSize=size+'px';
    while(size>floor&&inner.scrollWidth>limit+1){size-=0.5;inner.style.fontSize=size+'px';}
    if(inner.scrollWidth>limit+1){
      inner.style.whiteSpace='normal';
      inner.style.wordBreak='break-word';
      inner.style.hyphens='auto';
      inner.style.fontSize=floor+'px';
    }
  }
