      root.querySelectorAll('.sample-label-preview .lbl-sci').forEach(function(el){fitPassportTextEl_(el,{maxFont:22,minFont:10});});
      root.querySelectorAll('.passport-card-back .ppc-dd-sci').forEach(function(el){fitPassportTextEl_(el,{maxFont:15,minFont:10});});
      fitPhonePreviewFrame_();
