  function buildMissingItemsForWorkflowStep_(step){
    var s=state.specimen,h=workflowOriginHelpers(),out=[],skipPaleo=s.photoMode==='paleo_restoration',skipHistoric=s.photoMode==='historic_illustration';
    function pushItem(label,to,hint){out.push({label:label,to:to,hint:hint});}
    if(step===0&&!String(s.imageUrl||'').trim())pushItem('標本照片','#cg-step-0 .cg-upload-zone','請至少上傳一張標本照片');
    if(step===1&&!(state.ai.selected||state.ai.skipped||String(s.scientificName||'').trim().length>=3)){if(state.ai.loading)pushItem('快速辨識','#cg-step-1','辨識進行中，請稍候');else if(!state.ai.skipped&&!state.ai.selected)pushItem('快速辨識／學名','#cg-step-1','請套用候選、輸入至少 3 字元學名，或按「跳過辨識」');}
    if(step===2){
      if(!String(s.scientificName||'').trim())pushItem('學名','#cg-step-2 input[data-sp="scientificName"]','請選擇或輸入學名');
      if(!specimenHasUserTags())pushItem('標籤','#cg-field-tags','請至少新增一筆輸入標籤');
      if(!String(s.specimenCode||s.catalogNumber||'').trim())pushItem('館號／標本編號','#cg-step-2 input[data-sp="catalogNumber"]','請補上館號或標本編號');
      if(!String(s.satId||'').trim())pushItem('SAT ID','#cg-step-2 input[data-sp="satId"]','請補上 SAT ID');
      if(!s.taxonomyKey)pushItem('標本類群','#cg-step-2 .cg-cat-select-wrap','請選擇標本類群');
      if(!String(s.taxonomy||'').trim()||String(s.taxonomy||'').trim().length<2)pushItem('分類階層','#cg-step-2 textarea[data-sp="taxonomy"]','請補上分類階層');
      if(skipPaleo&&!paleoWorkflowLogicOk_()){var paleoTo=state.specimen.paleoEvidenceOther?'#cg-paleo-restore-panel textarea[data-sp="paleoRestorationLogic"]':'#cg-paleo-restore-panel .cg-paleo-ev-cards';pushItem('還原依據',paleoTo,paleoWorkflowLogicMissingHint_());}
    }
    if(step===3){
      if(!s.originType)pushItem('紀錄類型','#cg-step-3 select[data-sp="originType"]','請選擇紀錄類型');
      if(!h.visOk)pushItem('是否公開','#cg-step-3 [data-cg-field="visibility"] select','請選擇是否公開');
      if(!skipPaleo&&!skipHistoric&&!h.hasSource){
        var ot=s.originType;
        if(ot==='document_record'){
          if(!String(s.sourceUrl||'').trim())pushItem('文獻來源 URL','#cg-step-3 input[data-sp="sourceUrl"]','請填寫 DOI、書目或館藏查詢頁');
        }else if(ot==='ecological_photo'){
          if(!String(s.date||'').trim())pushItem('觀察日期','#cg-step-3 input[data-sp="date"]','請填寫觀察或拍攝日期');
          if(!String(s.observerName||s.collector||'').trim()&&!String(s.locality||'').trim())pushItem('觀察者或地點','#cg-step-3 input[data-sp="observerName"]','請填寫觀察者、紀錄者或地點');
        }else if(ot==='captive_bred'){
          if(!String(s.captiveGen||s.parentOrigin||s.emergeDate||s.breedingLine||'').trim())pushItem('飼育紀錄','#cg-step-3 select[data-sp="captiveGen"]','請填寫世代、親本來源或羽化日等飼育資訊');
        }else if(ot==='prehistoric_bio'){
          if(!s.sourceConfirmed&&!String(s.archSiteName||'').trim())pushItem('遺址名稱','#cg-step-3 input[data-sp="archSiteName"]','請填寫遺址或調查區，或勾選來源已確認');
        }else if(ot==='fossil_specimen'){
          if(!s.sourceConfirmed&&!String(s.geoFormation||'').trim())pushItem('地層／岩組','#cg-step-3 input[data-sp="geoFormation"]','請填寫地層名稱，或勾選來源已確認');
        }else if(ot==='other'){
          if(!String(s.locality||'').trim()&&!String(s.sourceUrl||'').trim())pushItem('地點或來源 URL','#cg-step-3 input[data-sp="locality"]','請補上地點描述或來源連結');
        }else{
          if(!String(s.locality||'').trim()&&!String(s.latitude||'').trim())pushItem('採集地點','#cg-step-3 input[data-sp="locality"]','請補上採集地點或座標');
          if(!String(s.date||'').trim())pushItem('紀錄日期','#cg-step-3 input[data-sp="date"]','請填寫採集、觀察或紀錄日期');
        }
        if(!s.sourceConfirmed&&!h.hasSource)pushItem('來源確認','#cg-step-3 input[data-sp-check="sourceConfirmed"]','請補齊來源欄位，或勾選「來源資訊未知但已確認」');
      }
    }
    if(step===4){
      var a=stepLicenseAccessMissing(),i;
      for(i=0;i<a.length;i++){
        if(a[i].indexOf('授權')>=0)pushItem('授權條款','#cg-step-4 select[data-sp="license"]','請選擇授權條款');
        else if(a[i].indexOf('存取')>=0)pushItem('存取模式','#cg-step-4 select[data-sp="accessMode"]','請選擇存取模式');
        else if(a[i].indexOf('QR')>=0)pushItem('卡片護照 QR 網址','#cg-step-4 input[data-qr-kind="passport"][data-qr="qrUrl"]','啟用護照 QR 時請填寫 QR 網址');
      }
      if(stepPassportStyleMissing().length)pushItem('卡片材質','#cg-step-4 [data-passport-material-select]','請選擇卡片材質');
    }
    if(step===5){
      var w=state.labelWorkflow||{};
      if(!w.mode)pushItem('樣本標籤選項','#cg-step-5 .cg-label-workflow-choice','請選擇製作或略過樣本標籤');
      if(w.mode==='make'&&state.label.showQr&&!String(state.label.qrUrl||'').trim())pushItem('標籤 QR 網址','#cg-step-5 input[data-qr-kind="label"][data-qr="qrUrl"]','啟用標籤 QR 時請填寫網址');
    }
    return out;
  }
