  function ensurePaleoSpecimenFields_(){var s=state.specimen;if(s.paleoRestorationLogic==null)s.paleoRestorationLogic='';if(s.paleoEvidenceFossil==null)s.paleoEvidenceFossil=false;if(s.paleoEvidenceLiterature==null)s.paleoEvidenceLiterature=false;if(s.paleoEvidenceComparative==null)s.paleoEvidenceComparative=false;if(s.paleoEvidenceInstitutional==null)s.paleoEvidenceInstitutional=false;if(s.paleoEvidenceArtistic==null)s.paleoEvidenceArtistic=false;if(s.paleoEvidenceOther==null)s.paleoEvidenceOther=false;if(s.paleoReferenceLinks==null)s.paleoReferenceLinks='';if(s.paleoFossilCatalogRef==null)s.paleoFossilCatalogRef='';if(s.paleoRestorationScore==null)s.paleoRestorationScore=0;if(s.paleoRestorationGrade==null)s.paleoRestorationGrade='';if(s.paleoApiSummary==null)s.paleoApiSummary='';}
  function paleoReferenceLinksList_(raw){return String(raw||'').split(/\r?\n/).map(function(u){return String(u||'').trim();}).filter(Boolean);}
  function isPaleoRefUrl_(u){u=String(u||'').trim();return/^https?:\/\//i.test(u)||/^doi:/i.test(u);}
