  function paleoEvidenceOptions_(){return[['fossil','化石／標本','標本、對照化石或田野編號'],['literature','文獻／復原圖','論文、圖版或公開復原圖'],['comparative','比較解剖','近緣現生種或同源結構'],['institutional','館藏／授權','館方圖檔或授權文件'],['artistic','藝術推論','色彩、構圖或缺失部位推測'],['other','其他','未列於上列者，需文字說明']];}
  function paleoEvidenceCardHtml_(key,title,hint,on){return'<label class="cg-paleo-ev-card'+(on?' is-on':'')+'"><input type="checkbox" class="cg-paleo-ev-card__input" data-paleo-ev="'+key+'" '+(on?'checked':'')+'><span class="cg-paleo-ev-card__tick" aria-hidden="true"></span><span class="cg-paleo-ev-card__title">'+esc(title)+'</span><span class="cg-paleo-ev-card__hint">'+esc(hint)+'</span></label>';}
  function paleoEvidenceCardsHtml_(s){return paleoEvidenceOptions_().map(function(row){return paleoEvidenceCardHtml_(row[0],row[1],row[2],paleoEvidenceOn_(row[0],s));}).join('');}
  function paleoRefLinksRowsForUi_(){var filled=paleoReferenceLinksList_(state.specimen.paleoReferenceLinks),slots=state.paleoRestore&&state.paleoRestore.refUiSlots,n=slots?Math.max(2,Math.min(6,slots)):Math.max(2,Math.min(6,filled.length+1)),rows=filled.slice();while(rows.length<n)rows.push('');return rows;}
