  function paleoReferenceLinksRowsHtml_(){var rows=paleoRefLinksRowsForUi_(),rowHtml=rows.map(function(u,i){var canRemove=rows.length>2;return'<div class="cg-paleo-ref-row"><span class="cg-paleo-ref-row__n">'+String(i+1)+'</span><input type="url" class="cg-paleo-ref-input" data-paleo-ref-url value="'+attr(u)+'" placeholder="https://doi.org/… 或 doi:10.xxxx/…" autocomplete="url"><button type="button" class="cg-btn cg-btn--ghost cg-paleo-ref-remove" data-paleo-ref-remove title="移除此列"'+(canRemove?'':' disabled')+'>×</button></div>';}).join('');var addDisabled=rows.length>=6?' disabled':'';return'<div class="cg-paleo-ref-list" data-paleo-ref-list>'+rowHtml+'</div><button type="button" class="cg-btn cg-btn--ghost cg-paleo-ref-add" data-paleo-ref-add'+addDisabled+'>＋ 再加一則連結</button>';}
