  function removePaleoRefRow_(btn){var row=btn&&btn.closest?btn.closest('.cg-paleo-ref-row'):null;if(!row)return;var links=[];document.querySelectorAll('#'+APP_ID+' [data-paleo-ref-url]').forEach(function(inp){if(inp.closest('.cg-paleo-ref-row')===row)return;var v=String(inp.value||'').trim();if(v)links.push(v);});state.specimen.paleoReferenceLinks=links.join('\n');syncPaleoSourceUrlFromRefs_();state.paleoRestore=state.paleoRestore||{};state.paleoRestore.refUiSlots=Math.max(2,document.querySelectorAll('#'+APP_ID+' [data-paleo-ref-url]').length-1);recalcPaleoRestorationScore_();renderPreservingFocus();}
  function paleoWorkflowChecklistHtml_(){ensurePaleoSpecimenFields_();var s=state.specimen,hasEv=paleoHasAnyEvidence_(),refs=paleoReferenceLinksValidCount_(s.paleoReferenceLinks),logicOk=!s.paleoEvidenceOther||paleoLogicCharCount_()>=40,allOk=paleoWorkflowLogicOk_();function item(done,label){return'<li class="cg-paleo-checklist__item'+(done?' is-done':'')+'"><span class="cg-paleo-checklist__mark" aria-hidden="true">'+(done?'✓':'○')+'</span><span>'+esc(label)+'</span></li>';}var items=[item(hasEv,'至少一項還原依據'),item(!s.paleoEvidenceOther||logicOk,s.paleoEvidenceOther?'其他說明 ≥40 字':'其他說明（免填）'),item(refs>0,'參考連結 '+refs+' 則（選填，加分）')];return'<ul class="cg-paleo-checklist'+(allOk?' is-complete':'')+'" aria-label="還原依據完成度">'+items.join('')+'</ul>';}
