  function buildPaleoApiSummary_(row){row=normalizeTaxonResult(row)||{};var bits=[row.source||'API',row.scientificName||row.species||''];if(row.pbdbTxnId)bits.push('PBDB txn '+row.pbdbTxnId);if(row.pbdbInterval)bits.push(row.pbdbInterval);if(row.taxonomy)bits.push(row.taxonomy);return bits.filter(Boolean).join(' · ').slice(0,420);}
  function recalcPaleoRestorationScore_(){if(!isPaleoRestorationMode_())return 0;var s=state.specimen,score=0;if(String(s.scientificName||'').trim().length>=3)score+=6;if(String(s.taxonomy||'').trim().length>=8)score+=6;if(String(s.pbdbTxnId||'').trim())score+=12;else if(String(s.gbifId||'').trim()||String(s.colId||'').trim())score+=6;if(String(s.geoAgeSystem||'').trim()||String(s.archCulturePhase||'').trim())score+=10;if(String(s.habitat||'').trim())score+=4;if(paleoHasAnyEvidence_())score+=8;if(s.paleoEvidenceFossil)score+=5;if(s.paleoEvidenceLiterature)score+=5;if(s.paleoEvidenceComparative)score+=4;if(s.paleoEvidenceInstitutional)score+=4;if(s.paleoEvidenceArtistic)score+=2;if(s.paleoEvidenceOther)score+=2;var refN=paleoReferenceLinksValidCount_(s.paleoReferenceLinks);score+=Math.min(refN,4)*4;var logic=String(s.paleoRestorationLogic||'').trim(),ll=logic.length;if(s.paleoEvidenceOther){if(ll>=40)score+=8;if(ll>=120)score+=6;if(/化石|文獻|對照|復原|還原|PBDB|測年|解剖|骨骼|羽毛|皮膚|軟組織|同位素|CT|μCT|館藏|標本|地層|系統發育|phylogen/i.test(logic))score+=8;}else if(ll>=40)score+=4;if(String(s.paleoFossilCatalogRef||'').trim())score+=4;if(String(s.sourceUrl||'').trim())score+=3;if(String(s.archReportRef||'').trim()||String(s.archChronometry||'').trim())score+=4;if(String(s.paleoApiSummary||'').trim())score+=5;score=clamp(score,0,100);s.paleoRestorationScore=score;s.paleoRestorationGrade=paleoGradeFromScore_(score);return score;}
  function schedulePaleoScoreRecalc_(){clearTimeout(timers.paleoScore);timers.paleoScore=setTimeout(function(){recalcPaleoRestorationScore_();renderPreservingFocus();},280);}
  function paleoTaxonomyHitSourceRank_(r){var s=String(r&&r.source||'');if(s==='PBDB')return 0;if(s==='GBIF')return 1;if(s.indexOf('Catalogue')>=0||s==='CoL')return 2;if(s.indexOf('ELC')===0)return 3;return 4;}
